-- Field fire safety images for lesson 1.8 (bn)
UPDATE training_chapters
SET
  content = '{"level_id":"1.8","badge_name":"সুরক্ষা কবচ","level_title":"মাঠে আগুন লাগলে করণীয়","mission_briefing":"বিদ্যুৎ এবং আগুন—দুটিই প্রকৃতির আদিম এবং শক্তিশালী রূপ। একজন লাইনম্যান হিসেবে আপনাকে দুটিকেই সম্মান এবং বুদ্ধিমত্তার সাথে মোকাবিলা করতে হবে। বৈদ্যুতিক আগুন সাধারণ আগুন থেকে সম্পূর্ণ আলাদা এবং ভুল পদক্ষেপে এটি আরও ভয়ংকর হয়ে উঠতে পারে। এই লেভেলের মিশন হলো আগুনের চরিত্র বোঝা এবং সঠিক অস্ত্র ব্যবহার করে একজন প্রশিক্ষিত ফায়ার ওয়ার্ডেনের মতো পরিস্থিতি নিয়ন্ত্রণ করা।","sections":[{"title":"আগুনের প্রকারভেদ এবং আপনার রণকৌশল","points":[{"item_name":"১. শত্রুকে চিনুন: আগুনের শ্রেণীবিভাগ","image_name":"/images/loader/fire_class_abc.webp","image_caption":"Class A / B / C — কোন আগুন কোন Class","specifications":"মাঠের কাজে আপনাকে মূলত এই আগুনের মোকাবিলা করতে হতে পারে:\n• Class B: দাহ্য তরল — Transformer Oil, ডিজেল\n• Class C: Live Electrical সরঞ্জাম বা Circuit\n• Class A: সাধারণ দাহ্য — শুকনো ঘাস, কাঠ, কাগজ","importance":"কোন Class-এর আগুন, তার ওপর নির্ভর করে নেভানোর পদ্ধতি। ভুল পদ্ধতিতে আগুন বাড়ে এবং জীবন বিপন্ন হয়।","daily_check":"গাড়ি ও Transformer-এ সঠিক Class-এর Fire Extinguisher আছে কিনা দেখুন।"},{"item_name":"২. জল: যখন বন্ধু শত্রুতে পরিণত হয়","image_name":"/images/loader/fire_no_water_bc.webp","image_caption":"Class B ও C — জল দেবেন না","specifications":"Class B ও Class C-তে জল কঠোরভাবে নিষিদ্ধ।\n• Class C (বৈদ্যুতিক): জল বিদ্যুৎ পরিবাহী — Shock ঝুঁকি।\n• Class B (তেল): তেল জলে ভাসে — আগুন ছড়ায়।\n• প্রথম কাজ: নিরাপদ হলে Power Source OFF করুন — Class C তখন Class A/B-তে পরিবর্তিত হতে পারে।","importance":"বৈদ্যুতিক বা তেলের আগুনে জল = আগুন শক্তিশালী করা। এই নিয়ম মনে রাখলে বড় বিপদ এড়ানো যায়।","daily_check":"বৈদ্যুতিক আগুনে প্রথমে Power বন্ধ করার পথ জানুন।"},{"item_name":"৩. আপনার সঠিক অস্ত্র: অগ্নি নির্বাপক যন্ত্র এবং বালি","image_name":"/images/loader/fire_extinguisher_types.webp","image_caption":"DCP (ABC) · CO2 (B+C) · বালি/মাটি","specifications":"আপনার প্রধান অস্ত্র:\n• DCP (Dry Chemical Powder) — ABC Class, ফিল্ডে সবচেয়ে উপযোগী\n• CO2 Extinguisher — Class B ও C-তে কার্যকর, Oxygen সরায়\n• বালি/শুকনো মাটি — ছোট তেলের আগুন, Oxygen বন্ধ","importance":"সঠিক Extinguisher = নিরাপদ নিয়ন্ত্রণ। ভুল অস্ত্র = নিজেই বিপদে।","daily_check":"Pressure Gauge সবুজ দাগে আছে কিনা দেখুন — তবেই ব্যবহারের জন্য Ready।"},{"item_name":"৪. PASS পদ্ধতি: অগ্নি নির্বাপক যন্ত্র ব্যবহারের গোল্ডেন রুল","image_name":"/images/loader/fire_pass_method.webp","image_caption":"PASS — Pull · Aim · Squeeze · Sweep","specifications":"Fire Extinguisher ব্যবহার — চার ধাপ:\n• P (Pull): Safety Pin টানুন\n• A (Aim): আগুনের গোড়ায় লক্ষ্য — শিখায় নয়\n• S (Squeeze): Handle/Lever চাপুন\n• S (Sweep): গোড়ায় এক পাশ থেকে অন্য পাশে Spray — সম্পূর্ণ না নিভা পর্যন্ত","importance":"PASS চাপের মুহূর্তেও সঠিক ব্যবহার শেখায়।","daily_check":"মনে মনে PASS অভ্যাস করুন — প্রয়োজনে ভাবতে হবে না।"}]}],"image_suggestion":"একটি পরিষ্কার ইনফোগ্রাফিক যেখানে PASS পদ্ধতির চারটি ধাপ (Pull, Aim, Squeeze, Sweep) ছবি দিয়ে বোঝানো হয়েছে। পাশে একটি জ্বলন্ত ট্রান্সফরমারের ছবি, যার ওপর জল দেওয়ার একটি প্রতীকের ওপর বড় লাল ক্রস চিহ্ন দেওয়া থাকবে।","pro_tip":{"title":"বিশেষ প্রো টিপস (Pro Tips)","content":["১. আগে Power OFF: Class C আগুনে প্রথম কাজ — নিরাপদ হলে Power Source বন্ধ।","২. বাতাসের দিক: বাতাস পেছনে রেখে দাঁড়ান — ধোঁয়া/তাপ আপনার দিকে নয়।","৩. Escape Route খোলা: পেছনে বেরোনোর পথ সবসময় পরিষ্কার — কোণঠাসা হবেন না।","৪. সীমা বুঝুন: নিয়ন্ত্রণের বাইরে গেলে Fire Brigade-কে Call — Hero নয়, Smart থাকুন।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","image_name":"/images/loader/fire_myth_refill_required.webp","image_caption":"ভুল: বাঁচিয়ে রাখা — সঠিক: Refill","myths":[{"myth":"অগ্নি নির্বাপক যন্ত্র একবার ব্যবহার করলে কিছুটা বাঁচিয়ে রাখা যায় পরের বারের জন্য।","reality":"ভুল। একবার ব্যবহার = চাপ বেরিয়ে যায় — পরে কাজ করে না। Refill-এর জন্য পাঠাতে হবে।"},{"myth":"ছোট আগুন, একটু পরেই নিজে থেকে নিভে যাবে।","reality":"আগুন দ্রুত বাড়ে — ছোট Spark কয়েক মিনিটে বড় Fire-এ পরিণত হতে পারে। ছোট থাকতেই Action নিন।"}]},"advanced_section":{"title":"এর পেছনের ইঞ্জিনিয়ারিং ও রসায়ন","facts":[{"title":"Fire Tetrahedron","content":"আগুনের জন্য চারটি জিনিস: Heat, Fuel, Oxygen, Chain Reaction। Extinguisher যেকোনো একটি সরিয়ে আগুন নেভায় — CO2 Oxygen সরায়, DCP Chain Reaction থামায়।"},{"title":"Saponification (Class K)","content":"রান্নাঘর/তেলের আগুনে (Class K) Wet Chemical Extinguisher সাবানের মতো Foam স্তর তৈরি করে Oxygen আটকায় — Saponification। ফিল্ডে প্রধানত DCP/CO2/বালি ব্যবহার হয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
